#include <bits/stdc++.h>
using namespace std;
class Solution {public:long long countPaths(int n,vector<vector<int>>& edges){vector<bool> prime(n+1,true);prime[0]=prime[1]=false;for(int p=2;p*p<=n;++p)if(prime[p])for(int j=p*p;j<=n;j+=p)prime[j]=false;vector<vector<int>> g(n+1);for(auto&e:edges){g[e[0]].push_back(e[1]);g[e[1]].push_back(e[0]);}vector<int> comp(n+1,-1),sz;for(int i=1;i<=n;++i)if(!prime[i]&&comp[i]<0){int id=sz.size(),count=0;vector<int> st={i};comp[i]=id;while(!st.empty()){int u=st.back();st.pop_back();++count;for(int v:g[u])if(!prime[v]&&comp[v]<0){comp[v]=id;st.push_back(v);}}sz.push_back(count);}long long ans=0;for(int p=1;p<=n;++p)if(prime[p]){long long seen=0;for(int v:g[p])if(!prime[v]){long long c=sz[comp[v]];ans+=c*(seen+1);seen+=c;}}return ans;}};
